\label{def:cpo}
	A $\,C^{2}$-immersed surface $\,S\subset\mathbf{R}^{3}\,$ has the \emph{central plane oval
	property}, or \emph{\textsf{cpo}}, if

	\begin{itemize}

		\item
		$S\,$ intersects \emph{at least one} affine plane transversally along an 
		{oval}, and

		\item
		\emph{Every} time $\,S\,$ intersects an affine plane transversally along an oval,
		that oval is \emph{central}
	\end{itemize}

\label{prop:blaschke}
	Suppose every plane transverse, and nearly tangent to, a smooth \emph{convex} surface 
	$\,S\subset\mathbf{R}^{3}\,$ cuts $\,S\,$ along a central loop. Then $\,S\,$ is quadric.

\label{def:sptfn}
	A map $\,\gamma:\mathbf{S}^{1}\to\mathbf{R}^{2}\,$ \emph{support parametrizes} an oval $\,\mathcal{O}\subset\mathbf{R}^{2}\,$ 
	if and only if it satisfies 

	\begin{equation}\label{eqn:spt}
		\gamma'(\theta) = \left|\gamma'(\theta)\right|\mathbf{i}\,e^{\mathbf{i}\theta}
		\quad\text{for all $\,\theta\in\mathbf{R}\,$}\,.
	\end{equation}

	Here we have identified $\,\mathbf{C}\approx\mathbf{R}^{2}\,$, and we regard
	$\,2\pi$-periodic maps $\,\mathbf{R}\to\mathbf{R}^{2}\,$ as maps from $\,\mathbf{S}^{1}\,$ to $\,\mathbf{R}^{2}\,$, 
	in the obvious ways. We use these identifications without 
	further comment below.

	Notice that (\ref{eqn:spt}) characterizes parametrization by the inverse of the 
	outer unit normal. This is a diffeomorphism $\,\mathcal{O}\to\mathbf{S}^{1}\,$ on any $\,C^{2}\,$ oval $\,\mathcal{O}$,
	a fact that yields both existence and uniqueness of the support parametrization.

	By an easy exercise, the \emph{support function} $\,h:\mathbf{R}\to\mathbf{R}\,$, given by 

	\begin{equation}\label{eqn:sptfn1}
		h(\theta) := \sup_{p\in\mathcal{O}}p\cdot e^{\mathbf{i}\theta}\,,
	\end{equation}

	determines $\,\gamma\,$ via the formula

	\begin{equation}\label{eqn:sptfn2}
		\gamma(\theta) = \left(h(\theta) + \mathbf{i}\,h'(\theta)\right)\,e^{\mathbf{i}\theta}\,.
	\end{equation}

\label{prop:H'''}
	An oval is an origin-centered \textbf{ellipse} 
	if and only if its support function $\,h\,$ satisfies 

	\begin{equation*}
		\left(h^{2}\right)''' + 4\left(h^{2}\right)' = 0\,.
	\end{equation*}

\label{def:eo}
Given the support parametrization $\,\gamma\,$ of an oval $\,\mathcal{O}\,$, we call the maps

\begin{equation*}
	{\textstyle{\frac{1}{2}}}\,\left(\gamma(\theta) +\gamma(\theta+\pi)\right)
	\quad\text{and}\quad
	{\textstyle{\frac{1}{2}}}\,\left(\gamma(\theta)-\gamma(\theta+\pi)\right)\,,
\end{equation*}

the \emph{even} and \emph{odd} parts of $\,\gamma\,$ respectively.

\label{obs:zeta'}
	We have
	\medskip











	\begin{equation*}
		\frac{\partial\zeta}{\partial\varepsilon}(0,\theta)
		= 
		\tau\cdot
		\Gamma\left(\theta,\,b\right) 	
	\end{equation*}

	and

	\begin{equation*}
		\frac{\partial^{2}\zeta}{\partial\varepsilon\,\partial\theta}\left(0,\theta\right)
		= 
		\tau\cdot \frac{\partial{\Gamma}}{\partial\theta}\left(\theta,b\right)\ .
	\end{equation*}

\label{obs:ftau}
	Suppose the horizontal cross-section $\,\mathcal{O}(z)\,$ of a transversely convex tube 
	$\,\mathcal{T}\,$ is central about $\,(\mathbf{c}(z),z)\,$ for each $\,-1<z<1\,$. 
	Then for each tilt-direction $\,\tau\in\mathbf{S}^{1}\,$, there exists a function 
	$\,f_{\tau}:\mathbf{S}^{1}\times(-1,1)\to\mathbf{R}\,$ such that
	\begin{equation*}
		\frac{\,\partial^{2}\mathbf{c}_{\varepsilon}}{\partial\varepsilon\,\partial\theta}\bigl(\theta,z\bigr)\Big|_{\varepsilon=0}
		=
		f_{\tau}(\theta,z)\,\mathbf{i}\,e^{\mathbf{i}\theta}
	\end{equation*}
	for all $\,(\theta,z)\in\mathbf{S}^{1}\times(-1,1)\,$.

We get $\,\mathbf{c}_{\varepsilon}\,$ by symmetrizing each member in a smooth family of support 
parametrizations:

\begin{equation*}
	\mathbf{c}_{\varepsilon}\,(\theta) = {\textstyle{\frac{1}{2}}}\left(\gamma_{\varepsilon}(\theta)+\gamma_{\varepsilon}(\theta+\pi)\right)
\end{equation*}

Indeed, our formula (\ref{eqn:cxe}) expresses $\,\mathbf{c}_{\varepsilon}\,$ in this way. It then follows
from the defining condition (\ref{eqn:spt}) for support parametrizations, that

\begin{equation*}
	\frac{\partial}{\partial\theta}\mathbf{c}_{\varepsilon} = {\textstyle{\frac{1}{2}}}\bigl(\left|\gamma_{\varepsilon}'(\theta)\right|+\left|\gamma_{\varepsilon}'(\theta+\pi)\right|\bigr)\mathbf{i}\,e^{\mathbf{i}\theta}
\end{equation*}

Differentiation with respect to $\,\varepsilon\,$ affects only the scalar coefficient of $\,\mathbf{i}\,e^{\mathbf{i}\theta}\,$ here, 
making the desired fact obvious.

\label{prop:pdes}
	On a transversely convex tube $\,\mathcal{T}\,$ with \textsf{cpo}, the transverse support 
	function $\,h\,$ of $\,\mathcal{T}^{*}\,$ satisfies two partial differential equations:
	\medskip	
	\begin{equation*}
		\bigl(h_{z}\left(h+h_{\theta\theta}\right)\bigr)_{\theta}
			+
		\bigl(h_{\theta}\left(h+h_{\theta\theta}\right)\bigr)_{z}
		=0
	\end{equation*}
	and
	\begin{equation*}
		h\,\left(h+h_{\theta\theta}\right)_{z}
		- 
		\left(h+h_{\theta\theta}\right)\,h_{z}
		=0\,.
	\end{equation*}

Differentiation with respect to $\,\theta\,$ annihilates $\,\mathbf{c}\,$ and $\,\mathbf{c}'\,$, and
	hence Lemma \ref{lem:dceps} combines with Observation \ref{obs:ftau} 
	to give

	\begin{eqnarray*}
		f_{\tau}
		&=&
		\mathbf{i}\,e^{\mathbf{i}\theta}\cdot \frac{\partial^{2}\mathbf{c}_{\varepsilon}}{\partial\varepsilon\,\partial\theta}\Big|_{\varepsilon=0}\\
		&&\\
		&=&
		\mathbf{i}\,e^{\mathbf{i}\theta}\cdot
		\bigl[
			\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)\Gamma^{*}_{\theta}
		\bigr]_{\theta}
		+
		\mathbf{i}\,e^{\mathbf{i}\theta}\cdot
		\bigl[
			\left(\tau\cdot\Gamma^{*}\right)\Gamma^{*}_{z}
		\bigr]_{\theta}
	\end{eqnarray*}

	Since $\,\Gamma^{*}\,$ support-parametrizes $\,\mathcal{O}(z)-\mathbf{c}(z)\,$ for each $\,z\,$, however, 
	we have $\,\Gamma^{*}_{\theta}=\left|\Gamma^{*}_{\theta}\right|\mathbf{i}\,e^{\mathbf{i}\theta}\,$. This is perpendicular
	to $\,-e^{\mathbf{i}\theta}=\left(\mathbf{i}\,e^{\mathbf{i}\theta}\right)_{\theta}\,$,  so the product rule 
	lets us rewrite the first term on the right above as\medskip

	\begin{equation*}





		\bigl[
			\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)
			\left|\Gamma^{*}_{\theta}\right|
		\bigr]_{\theta}\,.
	\end{equation*}


	To evaluate the second term, note that 
	$\,\Gamma^{*}_{\theta}\cdot\tau = \left|\Gamma^{*}_{\theta}\right|\mathbf{i}\,e^{\mathbf{i}\theta}\cdot\tau\,$, and\medskip

	\begin{equation*}
		\Gamma^{*}_{z\theta}\cdot\mathbf{i}\,e^{\mathbf{i}\theta} 
		= 
		\left(\Gamma^{*}_{\theta}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)_{z}
		=
		\left|\Gamma^{*}_{\theta}\right|_{z}\,.
	\end{equation*}


	Taking all these facts into account, our expansion of $\,f_{\tau}\,$ becomes\medskip

	\begin{eqnarray*}\label{eqn:216}


		f_{\tau}&=&
		\bigl[
			\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)
			\left|\Gamma^{*}_{\theta}\right|
		\bigr]_{\theta}\\
		&&\qquad	+\ 
		\left|\Gamma^{*}_{\theta}\right|\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\Gamma^{*}_{z}\cdot\mathbf{i}\,e^{\mathbf{i}\,\theta}
		\ +\ 
		\left(\tau\cdot\Gamma^{*}\right)\left|\Gamma^{*}_{\theta}\right|_{z}\nonumber
	\end{eqnarray*}

	Now separate multiples of $\,\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\,$ from those
	of $\,\tau\cdot e^{\mathbf{i}\theta}\,$, noting that
	$\,\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)_{\theta}=-\left(\tau\cdot e^{\mathbf{i}\theta}\right)\,$, and
	that by orthonormal expansion,\medskip	

	\begin{equation*}
		\tau\cdot\Gamma^{*}
		= 
		\left(\tau\cdot e^{\mathbf{i}\theta}\right)\left(e^{\mathbf{i}\theta}\cdot\Gamma^{*}\right)
		+
		\left(\tau\cdot \mathbf{i}\,e^{\mathbf{i}\theta}\right)\left(\mathbf{i}\,e^{\mathbf{i}\theta}\cdot\Gamma^{*}\right)\,.
	\end{equation*}


	Use these facts to expand $\,f_{\tau}\,$ further, collecting multiples of
	$\,\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\,$ and $\,\tau\cdot e^{\mathbf{i}\theta}\,$, and noticing that\medskip	

	\begin{equation*}
		\left(\Gamma^{*}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|_{z}
		+
		\left(\Gamma^{*}_{z}\cdot \mathbf{i}\,e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|
		=
		\bigl(\left(\Gamma^{*}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|\bigr)_{z}
	\end{equation*}

	to get

	\begin{eqnarray}\label{eqn:ftau}
		\lefteqn{f_{\tau}	=}\nonumber\\
		&&
		\left(\tau\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)
		\Bigl[
			\bigl(\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|\bigr)_{\theta}
			+
			\bigl(\left(\Gamma^{*}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|\bigr)_{z}
		\Bigr]
		\\
		&&\qquad\qquad +
		\left(\tau\cdot e^{\mathbf{i}\theta}\right)
		\Bigl[
			\left(e^{\mathbf{i}\theta}\cdot\Gamma^{*}\right)\left|\Gamma^{*}_{\theta}\right|_{z}
			-
			\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|
		\Bigr]\,.\nonumber
	\end{eqnarray}


	Now we invoke the central plane oval assumption, observing that
	\emph{when $\,\mathcal{T}\,$ has \textsf{cpo}, we must have $\,f_{\tau}\equiv 0\,$}.

	Indeed, \textsf{cpo}\ endows the tilted ovals $\,\bar\mathcal{O}(z,\varepsilon)\,$ with
	central symmetry for all $\,\tau\in\mathbf{S}^{1}\,$, all $\,-1<z<1\,$, and all 
	sufficiently small $\,\varepsilon\,$. As noted earlier, the projected ovals 
	$\,\mathcal{O}(z,\varepsilon)\,$ inherit that symmetry too, since the projection
	$\,(x,y,z)\to(x,y)\,$ induces an affine isomorphism from any non-vertical plane
	to $\,\mathbf{R}^{2}\,$. 

	Observation \ref{obs:centrix} then makes the centrix $\,\mathbf{c}_{\varepsilon}\,$
	of $\,\mathcal{O}(z,\varepsilon)\,$ constant (i.e. independent of $\,\theta\,$) for any tilt-direction
	$\,\tau\,$, any $\,|z|<1\,$ and all any sufficiently small $\,\varepsilon\,$.
	The vanishing condition (\ref{eqn:obstruct}) therefore obtains. Given
	Observation \ref{obs:ftau}, this forces $\,f_{\tau}\equiv 0\,$ as claimed.

	We may consequently set the right-hand side of (\ref{eqn:ftau}) equal to
	zero. But the resulting identity holds for \emph{any} tilt-direction $\,\tau=:e^{\mathbf{i}\phi}\in\mathbf{S}^{1}\,$,
	and \emph{the coefficients $\,\tau\cdot e^{\mathbf{i}\theta}=\cos(\phi-\theta)\,$ and 
	$\,\tau\cdot \mathbf{i}\,e^{\mathbf{i}\theta}=\sin(\phi-\theta)\,$ appearing there are clearly linearly independent 
	functions of $\,\tau\,$.} The terms they multiply must therefore vanish \emph{individually}. 
	In short, we now have
	\medskip

	\begin{eqnarray}
		0&=&
			\Bigl(\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|\Bigr)_{\theta}
			+
			\Bigl(\left(\Gamma^{*}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|\Bigr)_{z}
		\label{eqn:a}
		\\
		0&=&
			\left(e^{\mathbf{i}\theta}\cdot\Gamma^{*}\right)\left|\Gamma^{*}_{\theta}\right|_{z}
			-
			\left(\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta}\right)\left|\Gamma^{*}_{\theta}\right|
		\label{eqn:b}
	\end{eqnarray}


	For each $\,|z|<1\,$, the relationship between the support parametrization $\,\Gamma^{*}(\,\cdot,z)\,$ 	
	of $\,\mathcal{O}(z)\,$ and its support function $\,h(\,\cdot,z)\,$, as detailed in \S\ref{sec:ovals}, 
	now lets us write

	\begin{equation*}
		\Gamma^{*} = \left(h+\mathbf{i}\,h_{\theta}\right)\,e^{\mathbf{i}\theta}
		\quad\text{and}\quad
		\Gamma^{*}_{\theta} = \left(h+h_{\theta\theta}\right)\mathbf{i}\,e^{\mathbf{i}\theta}\,,
	\end{equation*}

	from which we can immediately deduce

	\begin{equation*}
		\begin{array}{rclcccl}
			\Gamma^{*}\cdot e^{\mathbf{i}\theta}&=& h\,,
			&\quad&
			\Gamma^{*}\cdot\mathbf{i}\,e^{\mathbf{i}\theta}&=&h_{\theta}\\
			\Gamma^{*}_{z}\cdot e^{\mathbf{i}\theta} &=& h_{z}\,,
			&\quad&
			\left|\Gamma^{*}_{\theta}\right|&=&h+h_{\theta\theta}\,,
		\end{array}
	\end{equation*}


	Substituting these into  (\ref{eqn:a}) and (\ref{eqn:b}) instantly gives the 
	differential equations we want.

\label{lem:split}
	If a transversely convex tube $\,\mathcal{T}\,$ in standard position has \textsf{cpo},
	then its rectification $\,\mathcal{T}^{*}\,$ splits.

It will clearly suffice to prove that the transverse support function $\,h\,$
	of $\,\Gamma^{*}\,$ factors as $\,h(z,\theta)=h(\theta)\,r(z)\,$. We know that
	$\,h(z,\theta)\,$ satisfies the two differential equations of Proposition
	\ref{prop:pdes}, and we start by noticing that the second equation there 
	forms the numerator of a quotient-rule calculation. 
	Specifically, it implies\medskip

	\begin{equation*}
		\frac{\partial}{\partial z}
		\left(
			\frac{h+h_{\theta\theta}}{h}
		\right)
		= 0\,,
	\end{equation*}

	from which we easily deduce

	\begin{equation}\label{eqn:floq}
		h_{\theta\theta}+h = q^{2}(\theta)\,h
	\end{equation}

	for some \emph{strictly} positive, $z$-independent function $\,q\,$ on $\,\mathbf{S}^{1}\,$.  
	We can assume positivity of $\,q\,$ because
	$\,\mathcal{O}(z)-\mathbf{c}(z)\,$ is origin-centered and strictly convex for each $\,z\,$, properties 
	that, by equations (\ref{eqn:sptfn1}) and (\ref{eqn:speed}), make both $\,h\,$ and 
	$\,h_{\theta\theta}+h\,$ strictly positive.

	In any case, since $\,q\,$ depends only on $\,\theta\,$, we see that the support functions 
	of the translated ovals $\,\mathcal{O}(z)-\mathbf{c}(z)\,$ all solve the same ordinary differential equation, 	namely (\ref{eqn:floq}). Such equations have independent solutions, of course, so by 
	itself, (\ref{eqn:floq}) leaves us short of splitting. But it lets us rewrite the 
	\emph{first} differential equation of Proposition \ref{prop:pdes} as

	\begin{equation}\label{eqn:ode2'}
		\bigl(h_{z}\,h\,q^{2}\bigr)_{\theta} + \bigl(h_{\theta}\,h\,q^{2}\bigr)_{z}=0\,.
	\end{equation}


	Since $\,h_{z}h\,$ and $\,h_{\theta}h\,$ are derivatives of (half) the
	\emph{squared} support function 

	\begin{equation*}
		H(\theta,z):=h^{2}(\theta,z)\,,
	\end{equation*}

	we can the exploit $z$-independence of $\,q\,$, and use $\,H_{z\theta}=H_{\theta z}\,$ 
	to rewrite (\ref{eqn:ode2'}) in the form of a first-order equation for $\,H_{z}\,$:

	\begin{equation*}
		2H_{z\theta}\,q^{2}+H_{z}\bigl(q^{2}\bigr)_{\theta} = 0\,.
	\end{equation*}

	Now multiply by $\,H_{z}\,$ to recognize that (\ref{eqn:ode2'}) actually reduces 
	to

	\begin{equation*}
		\bigl(H_{z}^{2}q^{2}\bigr)_{\theta}=0\,.
	\end{equation*}

	Evidently, there exists a $\theta$-independent function $\,\phi(z)\,$ such that

	\begin{equation*}
		H_{z}(\theta,z) = \phi(z)\big/q(\theta)\,.
	\end{equation*}


	Integrating with respect to $\,z\,$ then yields\medskip

	\begin{equation*}
		H(\theta,z) = H(\theta,0) + \frac{\Phi(z)}{q(\theta)}\,,
		\quad\text{where}\quad
		\Phi(z):=\int_{0}^{z}\phi(s)\,ds\,.
	\end{equation*}

	Rewrite this as  

	\begin{equation*}
		H(\theta,z) = H(\theta,0)\left(1 + \alpha(\theta)\Phi(z)\right)\,,
	\end{equation*}

	where

	\begin{equation*}
		\alpha(\theta):=\frac{1}{H(\theta,0)\,q(\theta)}\,.
	\end{equation*}

	Since $\,H=h^{2}\,$, and, as the support function of an origin-centered oval, $\,h(\theta,z)$
	is always positive, we see that $\,1+\alpha\,\Phi>0\,$ too. Hence

	\begin{equation}\label{eqn:presplit}
		h(\theta,z) = h(\theta,0)\sqrt{1+\alpha(\theta)\,\Phi(z)}\,.
	\end{equation}


	The continuity of $\,\alpha\,$ guarantees it a maximum value $\,\bar\alpha\,$ 
	at some point $\,\bar\theta\in\mathbf{S}^{1}\,$, and there, (\ref{eqn:presplit}) yields
	\medskip

	\begin{eqnarray*}
		h(\bar\theta,z) 
		&=& h(\bar\theta,0)\sqrt{1+\bar\alpha\,\Phi(z)}\\
		h_{\theta}(\bar\theta,z) 
		&=& h_{\theta}(\bar\theta,0)\sqrt{1+\bar\alpha\,\Phi(z)}\,.\rule{0pt}{6mm}
	\end{eqnarray*}


	These identities show that for any fixed $\,z\,$ with $\,|z|<1\,$, 
	the functions $\,h(\theta,z)\,$ and 
	$\,h(\theta,0)\sqrt{1+\bar\alpha\,\Phi(z)}\,$ both obey the same initial conditions at $\,\theta=\bar\theta\,$. 
	Since both also solve (\ref{eqn:floq}), Picard's uniqueness theorem forces them to agree 
	everywhere. 

	The Lemma consequently holds with
	\medskip

	\begin{equation*}
		r(z) = \sqrt{1+\bar\alpha\,\Phi(z)}
		\quad\text{and}\quad
		h(\theta) = h(\theta,0)\,.
	\end{equation*}

\label{prop:branch}
	Suppose $\,\mathcal{T}\,$ is a transversely convex tube with \textsf{cpo}.
	Then its rectification $\,\mathcal{T}^{*}\,$ is either
	\begin{itemize}

		\item[(i)] The cylinder over a central oval, or
		\smallskip

		\item[(ii)] Affinely congruent to a surface of revolution.
	\end{itemize}

\label{thm:main}
	A complete, connected $\,C^{2}$-immersed surface in $\,\mathbf{R}^{3}\,$ with  \textsf{cpo}\ is 
	either a cylinder, or quadric.

\label{thm:noskew}
	Suppose a $C^{2}$-immersed surface $\,M\subset\mathbf{R}^{3}\,$ crosses some plane transversally 
	along an oval. Then exactly one of the following holds:	
	\begin{itemize}

		\item[(i)] $S\,$ contains a skewloop.
		\smallskip

		\item[(ii)] $S\,$ is the cylinder over an oval.
		\smallskip

		\item[(iii)] $S\,$ is a non-cylindrical quadric.
	\end{itemize}

Our hypotheses explicitly guarantee the existence of at least one oval $\,\mathcal{O}\,$
	along which $\,M\,$ cuts an affine plane transversally. But they actually ensure that \emph{all} 
	such ovals are central. For otherwise, Lemma \ref{lem:gs} puts a skewloop on $\,M\,$. 
	It follows that $\,M\,$ has \textsf{cpo}, and the desired conclusion
	then follows from our Main Theorem \ref{thm:main}
